    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))
    if not centers:
        return out

    # Continuous rows/columns of 2s are the grid axes.
    row_axes = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= 0.7 * w]
    col_axes = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= 0.7 * h]

