        for rr in range(max(0, r - 1), min(h, r + 2)):
            for cc in range(max(0, c - 1), min(w, c + 2)):
                if (rr, cc) != (r, c) and out[rr][cc] not in (2, 3):
                    out[rr][cc] = 1

    if row_axes:
        # Extend marker-center columns across the image, with a new 1-ring
        # wherever they cross a horizontal 2-axis.
        marker_cols = sorted(set(c for _, c in centers))
        for c in marker_cols:
            for r in range(h):
                if out[r][c] == 0:
                    out[r][c] = 1
            for r in row_axes:
                if (r, c) not in centers:
                    paint_ring(r, c)
