        # Extend marker-center rows across the image, with a new 1-ring
        # wherever they cross a vertical 2-axis.
        marker_rows = sorted(set(r for r, _ in centers))
        for r in marker_rows:
            for c in range(w):
                if out[r][c] == 0:
                    out[r][c] = 1
            for c in col_axes:
                if (r, c) not in centers:
                    paint_ring(r, c)
    return out
''')
